  std::string server_name;
  std::string cpu_name;
  std::chrono::system_clock::time_point timestamp;
  int64_t hi = 0;
  int64_t timer = 0;
  int64_t net_tx = 0;
  int64_t net_rx = 0;
  int64_t block = 0;
  int64_t sched = 0;
};

