509	void MainWindow::UpdateRealtimeChart() {
510	    // 清除现有数据
511	    realtime_series_->clear();
512	    
513	    if (performance_records_.empty()) {
514	        return;
515	    }
516	    
517	    // 根据图表类型获取数据
518	    QString chart_type = ui->chartTypeCombo->currentText();
519	    
520	    // 获取最近60秒的数据
521	    QDateTime now = QDateTime::currentDateTime();
522	    QDateTime one_minute_ago = now.addSecs(-60);
523	    
524	    // 过滤最近60秒的数据点
525	    for (const auto& record : performance_records_) {
526	        if (record.timestamp >= one_minute_ago && record.timestamp <= now) {
527	            double value = 0.0;
528	            
529	            if (chart_type == "CPU") {
530	                value = record.cpu_percent;
531	            } else if (chart_type == "内存") {
532	                value = record.mem_used_percent;
533	            } else if (chart_type == "磁盘") {
534	                value = record.disk_util_percent;
535	            } else if (chart_type == "网络") {
536	                value = record.send_rate + record.rcv_rate;
537	            } else if (chart_type == "负载") {
538	                value = record.load_avg_1;
539	            }
540	            
541	            // 添加数据点，使用时间差作为X轴坐标
542	            double x = now.secsTo(record.timestamp);
543	            realtime_series_->append(x, value);
544	        }
545	    }
546	    
547	    // 更新图表标题
548	    realtime_chart_->setTitle(QString("%1 实时监控 - %2").arg(chart_type).arg(selected_server_));
549	}
