#include "mainwindow.h"
#include "ui_mainwindow.h"

#include <QMenu>
#include <QAction>
#include <QDebug>
#include <QDateTime>
#include <QPainter>
#include <QMouseEvent>

MainWindow::MainWindow(QWidget *parent)
    : QMainWindow(parent)
    , ui(new Ui::MainWindow)
    , grpc_client_(new GrpcClient("localhost:50051"))
    , data_fetch_thread_(new DataFetchThread(grpc_client_, this))
    , realtime_update_timer_(new QTimer(this)) {
    ui->setupUi(this);

    // 加载主题设置
    ThemeManager::Instance()->LoadSettings();

    // 初始化UI组件
    InitializeUI();

    // 初始化数据获取线程
    InitializeDataFetchThread();

    // 连接主题变化信号
    connect(ThemeManager::Instance(), &ThemeManager::ThemeChanged,
            this, &MainWindow::onThemeChanged);

    // 更新主题菜单选中状态
    UpdateThemeMenuState();
}

MainWindow::~MainWindow() {
    data_fetch_thread_->Stop();
    data_fetch_thread_->wait();
    delete data_fetch_thread_;
    delete grpc_client_;
    delete ui;
}

void MainWindow::InitializeUI() {
    // 初始化图表
    InitializeCharts();

    // 初始化服务器树形控件
    InitializeServerTree();

    // 初始化集群统计按钮
    InitializeClusterStatsButtons();

    // 设置默认时间范围（最近1小时）
    QDateTime now = QDateTime::currentDateTime();
    ui->startTimeEdit->setDateTime(now.addSecs(-3600));
    ui->endTimeEdit->setDateTime(now);

    // 初始化状态栏
    statusBar()->showMessage("就绪");

    // 设置图标
    setWindowIcon(QIcon(":/icons/logo.png"));
}

void MainWindow::InitializeCharts() {
    // ========== 实时图表初始化 ==========
    realtime_chart_ = new QtCharts::QChart();
    realtime_series_ = new QtCharts::QLineSeries();
    realtime_axisX_ = new QtCharts::QValueAxis();
    realtime_axisY_ = new QtCharts::QValueAxis();

    // 配置实时图表
    realtime_series_->setName("实时数据");
    realtime_chart_->addSeries(realtime_series_);
    realtime_chart_->addAxis(realtime_axisX_, Qt::AlignBottom);
    realtime_chart_->addAxis(realtime_axisY_, Qt::AlignLeft);
    realtime_series_->attachAxis(realtime_axisX_);
    realtime_series_->attachAxis(realtime_axisY_);

    // 设置轴范围
    realtime_axisX_->setRange(0, 60); // 显示最近60秒
    realtime_axisY_->setRange(0, 100); // 默认0-100%
    realtime_axisY_->setTitleText("百分比 (%)");

    // 创建图表视图
    auto realtime_chart_view = new QtCharts::QChartView(realtime_chart_);
    realtime_chart_view->setRenderHint(QPainter::Antialiasing);
    realtime_chart_view->setRubberBand(QtCharts::QChartView::RectangleRubberBand);
    realtime_chart_view->setMouseTracking(true);

    // 连接信号槽
    connect(realtime_chart_view, &QtCharts::QChartView::mousePress, 
            this, &MainWindow::on_realtimeChartMousePress);
    connect(realtime_chart_view, &QtCharts::QChartView::mouseRelease, 
            this, &MainWindow::on_realtimeChartMouseRelease);
    connect(realtime_chart_view, &QtCharts::QChartView::mouseMove, 
            this, &MainWindow::on_realtimeChartMouseMove);

    ui->realtimeChartLayout->addWidget(realtime_chart_view);

    // ========== 历史图表初始化 ==========
    history_chart_ = new QtCharts::QChart();
    history_series_ = new QtCharts::QLineSeries();
    history_axisX_ = new QtCharts::QDateTimeAxis();
    history_axisY_ = new QtCharts::QValueAxis();

    // 配置历史图表
    history_series_->setName("历史数据");
    history_chart_->addSeries(history_series_);
    history_chart_->addAxis(history_axisX_, Qt::AlignBottom);
    history_chart_->addAxis(history_axisY_, Qt::AlignLeft);
    history_series_->attachAxis(history_axisX_);
    history_series_->attachAxis(history_axisY_);

    // 设置轴范围
    QDateTime now = QDateTime::currentDateTime();
    history_axisX_->setRange(now.addSecs(-3600), now);
    history_axisY_->setRange(0, 100);
    history_axisY_->setTitleText("百分比 (%)");
    history_axisX_->setTitleText("时间");

    // 创建图表视图
    auto history_chart_view = new QtCharts::QChartView(history_chart_);
    history_chart_view->setRenderHint(QPainter::Antialiasing);
    history_chart_view->setRubberBand(QtCharts::QChartView::RectangleRubberBand);
    history_chart_view->setMouseTracking(true);

    // 连接信号槽
    connect(history_chart_view, &QtCharts::QChartView::mouseDoubleClick, 
            this, &MainWindow::on_historyChartDoubleClick);
    connect(history_chart_view, &QtCharts::QChartView::mouseMove, 
            this, &MainWindow::on_historyChartMouseMove);

    ui->historyChartLayout->addWidget(history_chart_view);
}

