void MainWindow::on_serverTreeWidget_itemClicked(QTreeWidgetItem *item, int column) {
    Q_UNUSED(column);

    // 判断是否为服务器节点
    if (item->parent() == nullptr) {
        // 是服务器节点，显示详细信息
        QString server_name = item->text(0);
        selected_server_ = server_name;

        // 更新数据获取线程的服务器名称
        data_fetch_thread_->SetServerName(server_name);

        // 查询并显示详细数据
        QueryServerDetail(server_name);

        // 更新状态栏
        statusBar()->showMessage(QString("当前服务器: %1").arg(server_name));
    }
}

void MainWindow::on_serverTreeWidget_customContextMenuRequested(const QPoint &pos) {
    QTreeWidgetItem *item = ui->serverTreeWidget->itemAt(pos);
    if (!item) return;

    QMenu menu(this);
    QAction *viewAction = menu.addAction("查看详情");
    QAction *refreshAction = menu.addAction("刷新数据");
    QAction *alarmAction = menu.addAction("设置告警");

    QAction *selectedAction = menu.exec(ui->serverTreeWidget->mapToGlobal(pos));
    if (selectedAction == viewAction) {
        on_serverTreeWidget_itemClicked(item, 0);
    } else if (selectedAction == refreshAction) {
        // 刷新服务器数据
        QString server_name = item->text(0);
        QueryServerDetail(server_name);
        statusBar()->showMessage(QString("正在刷新 %1 的数据...").arg(server_name));
    } else if (selectedAction == alarmAction) {
        // 显示告警配置对话框
        QString server_name = item->text(0);
        ShowAlarmConfigDialog(server_name);
    }
}

void MainWindow::on_queryButton_clicked() {
    if (selected_server_.isEmpty()) {
        statusBar()->showMessage("请先选择一个服务器");
