void MainWindow::on_chartTypeCombo_currentTextChanged(const QString &arg1) {
    // 根据图表类型调整Y轴范围
    if (arg1 == "CPU" || arg1 == "内存" || arg1 == "磁盘") {
        realtime_axisY_->setRange(0, 100);
        history_axisY_->setRange(0, 100);
        realtime_axisY_->setTitleText("百分比 (%)");
        history_axisY_->setTitleText("百分比 (%)");
    } else if (arg1 == "网络") {
        realtime_axisY_->setRange(0, 1000); // 默认1000 KB/s
        history_axisY_->setRange(0, 1000);
        realtime_axisY_->setTitleText("速率 (KB/s)");
        history_axisY_->setTitleText("速率 (KB/s)");
    } else if (arg1 == "负载") {
        realtime_axisY_->setRange(0, 4); // 默认0-4
        history_axisY_->setRange(0, 4);
        realtime_axisY_->setTitleText("负载值");
        history_axisY_->setTitleText("负载值");
    }

    // 更新实时图表标题
    realtime_chart_->setTitle(QString("%1 实时监控").arg(arg1));
    history_chart_->setTitle(QString("%1 历史趋势").arg(arg1));
