void MainWindow::on_anomalyListWidget_itemClicked(QListWidgetItem *item) {
    // 解析异常信息
    QString text = item->text();
    QStringList parts = text.split(" - ");
    if (parts.size() < 3) return;

    QString server_name = parts[1];
    QString metric_name = parts[2];

    // 选中对应的服务器
    SelectServerInTree(server_name);

    // 切换到对应的图表类型
    QString chart_type;
    if (metric_name.contains("CPU")) {
        chart_type = "CPU";
    } else if (metric_name.contains("内存")) {
        chart_type = "内存";
    } else if (metric_name.contains("磁盘")) {
        chart_type = "磁盘";
    } else if (metric_name.contains("负载")) {
        chart_type = "负载";
    }

    if (!chart_type.isEmpty()) {
        ui->chartTypeCombo->setCurrentText(chart_type);
    }

    statusBar()->showMessage(QString("显示 %1 的 %2 异常详情").arg(server_name).arg(metric_name));
}

