void MainWindow::QueryServerDetail(const QString& server_name) {
    // 构建时间范围
    QDateTime start_time = ui->startTimeEdit->dateTime();
    QDateTime end_time = ui->endTimeEdit->dateTime();

    // 查询性能数据
    std::vector<PerformanceRecord> records;
    if (grpc_client_->QueryPerformance(server_name.toStdString(), start_time, end_time, records)) {
        performance_records_ = records;
        UpdateHistoryChart(records);
        statusBar()->showMessage(QString("已更新 %1 的历史数据").arg(server_name));
    }

    // 查询异常数据
    std::vector<AnomalyRecord> anomalies;
    if (grpc_client_->QueryAnomaly(server_name.toStdString(), start_time, end_time, anomalies)) {
        anomaly_records_ = anomalies;
        UpdateAnomalyList(anomalies);
    }
}

void MainWindow::UpdateRealtimeChart() {
    // 清除现有数据
    realtime_series_->clear();

    if (performance_records_.empty()) {
        return;
    }

    // 根据图表类型获取数据
    QString chart_type = ui->chartTypeCombo->currentText();

    // 获取最近60秒的数据
    QDateTime now = QDateTime::currentDateTime();
    QDateTime one_minute_ago = now.addSecs(-60);

    // 过滤最近60秒的数据点
    for (const auto& record : performance_records_) {
        if (record.timestamp >= one_minute_ago && record.timestamp <= now) {
            double value = 0.0;

            if (chart_type == "CPU") {
                value = record.cpu_percent;
            } else if (chart_type == "内存") {
                value = record.mem_used_percent;
            } else if (chart_type == "磁盘") {
                value = record.disk_util_percent;
            } else if (chart_type == "网络") {
                value = record.send_rate + record.rcv_rate;
            } else if (chart_type == "负载") {
                value = record.load_avg_1;
            }

            // 添加数据点，使用时间差作为X轴坐标
            double x = now.secsTo(record.timestamp);
            realtime_series_->append(x, value);
        }
    }

    // 更新图表标题
    realtime_chart_->setTitle(QString("%1 实时监控 - %2").arg(chart_type).arg(selected_server_));
}

void MainWindow::UpdateHistoryChart(const std::vector<PerformanceRecord>& records) {
    // 清除现有数据
    history_series_->clear();

    if (records.empty()) {
        return;
    }

    // 根据图表类型获取数据
    QString chart_type = ui->chartTypeCombo->currentText();

    // 添加数据点
    for (const auto& record : records) {
        double value = 0.0;

        if (chart_type == "CPU") {
            value = record.cpu_percent;
        } else if (chart_type == "内存") {
            value = record.mem_used_percent;
        } else if (chart_type == "磁盘") {
            value = record.disk_util_percent;
        } else if (chart_type == "网络") {
            value = record.send_rate + record.rcv_rate;
        } else if (chart_type == "负载") {
            value = record.load_avg_1;
        }

        // 添加数据点，使用时间作为X轴坐标
        qint64 x = record.timestamp.toMSecsSinceEpoch();
        history_series_->append(x, value);
    }

    // 更新图表标题
    history_chart_->setTitle(QString("%1 历史趋势 - %2").arg(chart_type).arg(selected_server_));
}

void MainWindow::UpdateServerTree(const std::vector<ServerScoreSummary>& servers) {
    ui->serverTreeWidget->clear();

    for (const auto& server : servers) {
        // 创建服务器节点
        QTreeWidgetItem *server_item = new QTreeWidgetItem(ui->serverTreeWidget);
        server_item->setText(0, QString::fromStdString(server.server_name));
        server_item->setIcon(0, QIcon(server.online ? ":/icons/online.png" : ":/icons/offline.png"));

        // 创建子节点显示基本信息
        QTreeWidgetItem *cpu_item = new QTreeWidgetItem(server_item);
        cpu_item->setText(0, QString("CPU: %.1f%%").arg(server.cpu_percent));

        QTreeWidgetItem *mem_item = new QTreeWidgetItem(server_item);
        mem_item->setText(0, QString("内存: %.1f%%").arg(server.mem_used_percent));

        QTreeWidgetItem *disk_item = new QTreeWidgetItem(server_item);
        disk_item->setText(0, QString("磁盘: %.1f%%").arg(server.disk_util_percent));

        QTreeWidgetItem *load_item = new QTreeWidgetItem(server_item);
        load_item->setText(0, QString("负载: %.2f").arg(server.load_avg_1));

        QTreeWidgetItem *score_item = new QTreeWidgetItem(server_item);
        score_item->setText(0, QString("评分: %.2f").arg(server.score));

        QTreeWidgetItem *status_item = new QTreeWidgetItem(server_item);
        status_item->setText(0, server.online ? "状态: 在线" : "状态: 离线");
        status_item->setIcon(0, QIcon(server.online ? ":/icons/online.png" : ":/icons/offline.png"));
    }

    // 自动展开第一个服务器节点
    if (ui->serverTreeWidget->topLevelItemCount() > 0) {
        ui->serverTreeWidget->expandItem(ui->serverTreeWidget->topLevelItem(0));
    }
}

void MainWindow::UpdateClusterStats(const ClusterStats& stats) {
    ui->totalServersButton->setText(QString("总服务器数: %1").arg(stats.total_servers));
    ui->onlineServersButton->setText(QString("在线: %1").arg(stats.online_servers));
    ui->offlineServersButton->setText(QString("离线: %1").arg(stats.offline_servers));
    ui->avgScoreButton->setText(QString("平均评分: %.2f").arg(stats.avg_score));
    ui->bestServerButton->setText(QString("最佳服务器: %1").arg(QString::fromStdString(stats.best_server)));
    ui->worstServerButton->setText(QString("最差服务器: %1").arg(QString::fromStdString(stats.worst_server)));
}

void MainWindow::UpdateAnomalyList(const std::vector<AnomalyRecord>& anomalies) {
    ui->anomalyListWidget->clear();

    for (const auto& anomaly : anomalies) {
        QString severity_color = anomaly.severity == "CRITICAL" ? "red" : "yellow";
        QString item_text = QString("<font color='%1'>%2</font> - %3 - %4 - %5: %6/%7")
                .arg(severity_color)
                .arg(anomaly.timestamp.toString("yyyy-MM-dd hh:mm:ss"))
                .arg(QString::fromStdString(anomaly.server_name))
                .arg(QString::fromStdString(anomaly.metric_name))
                .arg(QString::fromStdString(anomaly.anomaly_type))
                .arg(anomaly.value)
                .arg(anomaly.threshold);

        QListWidgetItem *item = new QListWidgetItem(item_text);
        ui->anomalyListWidget->addItem(item);
    }
}

void MainWindow::SelectServerInTree(const QString& server_name) {
    // 查找并选中指定服务器
    for (int i = 0; i < ui->serverTreeWidget->topLevelItemCount(); ++i) {
        QTreeWidgetItem *item = ui->serverTreeWidget->topLevelItem(i);
        if (item->text(0) == server_name) {
            ui->serverTreeWidget->setCurrentItem(item);
            on_serverTreeWidget_itemClicked(item, 0);
            break;
        }
    }
}

