#pragma once

#include <string>
#include <vector>
#include <QDateTime>

// 服务器评分摘要
struct ServerScoreSummary {
    std::string server_name;
    float score;
    QDateTime last_update;
    bool online;
    float cpu_percent;
    float mem_used_percent;
    float disk_util_percent;
    float load_avg_1;
};

// 性能数据记录
struct PerformanceRecord {
    std::string server_name;
    QDateTime timestamp;
    float cpu_percent;
    float usr_percent;
    float system_percent;
    float nice_percent;
    float idle_percent;
    float io_wait_percent;
    float irq_percent;
    float soft_irq_percent;
    float load_avg_1;
    float load_avg_3;
    float load_avg_15;
    float mem_used_percent;
    float mem_total;
    float mem_free;
    float mem_avail;
    float disk_util_percent;
    float send_rate;
