458	void DataFetchThread::run() {
459	    while (running_) {
460	        // 获取最新评分（每次循环都获取）
461	        FetchLatestScore();
462	        
463	        // 获取当前选中服务器的详细数据
464	        QString server_name;
465	        {
466	            QMutexLocker locker(&mutex_);
467	            server_name = server_name_;
468	        }
469	        
470	        if (!server_name.isEmpty()) {
471	            FetchPerformanceData();
472	            FetchTrendData();
473	            FetchAnomalyData();
474	            FetchDetailData();
