730	class ThemeManager : public QObject {
731	    Q_OBJECT
732	
733	public:
734	    enum Theme {
735	        Dark,
736	        Light,
737	        Classic
738	    };
739	    Q_ENUM(Theme)
740	
741	    static ThemeManager* Instance() {
742	        static ThemeManager instance;
743	        return &instance;
744	    }
745	
746	    void SetTheme(Theme theme) {
747	        current_theme_ = theme;
748	        ApplyTheme();
749	        SaveSettings();
750	        emit ThemeChanged(theme);
751	    }
752	
753	    Theme GetTheme() const {
754	        return current_theme_;
755	    }
756	
757	    QString GetThemeName() const {
758	        switch (current_theme_) {
759	            case Dark:   return tr("深色主题");
760	            case Light:  return tr("浅色主题");
761	            case Classic: return tr("经典主题");
762	            default:     return tr("未知");
763	        }
764	    }
765	
766	    void LoadSettings() {
767	        QSettings settings("MonitorSystem", "QtClient");
768	        int theme = settings.value("theme", static_cast<int>(Dark)).toInt();
769	        current_theme_ = static_cast<Theme>(theme);
770	        ApplyTheme();
771	    }
772	
773	signals:
774	    void ThemeChanged(Theme theme);
775	
776	private:
777	    ThemeManager() : current_theme_(Dark) {}
778	    ThemeManager(const ThemeManager&) = delete;
779	    ThemeManager& operator=(const ThemeManager&) = delete;
780	
781	    void ApplyTheme() {
782	        QString qss_file;
783	        
784	        switch (current_theme_) {
785	            case Dark:
786	                qss_file = ":/styles/dark_theme.qss";
787	                break;
788	            case Light:
789	                qss_file = ":/styles/light_theme.qss";
790	                break;
791	            case Classic:
792	                qss_file = ":/styles/main.qss";
793	                break;
794	        }
795	
796	        QFile file(qss_file);
797	        if (file.open(QFile::ReadOnly | QFile::Text)) {
798	            QString style_sheet = QString::fromUtf8(file.readAll());
799	            qApp->setStyleSheet(style_sheet);
800	            file.close();
801	            qDebug() << "Theme applied:" << GetThemeName();
802	        } else {
803	            qWarning() << "Failed to load theme file:" << qss_file;
804	        }
805	    }
806	
807	    void SaveSettings() {
808	        QSettings settings("MonitorSystem", "QtClient");
809	        settings.setValue("theme", static_cast<int>(current_theme_));
810	    }
811	
812	    Theme current_theme_;
813	};
