#include "grpc_client.h"
#include "time_utils.h"
#include "monitor_data.h"

#include <QDebug>

GrpcClient::GrpcClient(const std::string& server_address) {
    // 创建gRPC通道
    channel_ = grpc::CreateChannel(server_address, grpc::InsecureChannelCredentials());

    // 创建服务存根
    stub_ = monitor::proto::QueryService::NewStub(channel_);
}

GrpcClient::~GrpcClient() {
}

bool GrpcClient::GetLatestScore(std::vector<ServerScoreSummary>& servers, ClusterStats& stats) {
    monitor::proto::QueryLatestScoreRequest request;
    monitor::proto::QueryLatestScoreResponse response;
    grpc::ClientContext context;

    // 调用RPC
    grpc::Status status = stub_->QueryLatestScore(&context, request, &response);
    if (!status.ok()) {
        qDebug() << "GetLatestScore RPC failed: " << status.error_message().c_str();
        return false;
    }

    // 转换服务器评分数据
    for (const auto& server : response.servers()) {
        ServerScoreSummary summary;
        summary.server_name = server.server_name();
        summary.score = server.score();
        summary.last_update = TimeUtils::TimestampToQDateTime(server.last_update());
        summary.online = (server.status() == monitor::proto::ONLINE);
        summary.cpu_percent = server.cpu_percent();
        summary.mem_used_percent = server.mem_used_percent();
        summary.disk_util_percent = server.disk_util_percent();
        summary.load_avg_1 = server.load_avg_1();
        servers.push_back(summary);
    }

    // 转换集群统计数据
    const auto& cluster_stats = response.cluster_stats();
    stats.total_servers = cluster_stats.total_servers();
    stats.online_servers = cluster_stats.online_servers();
    stats.offline_servers = cluster_stats.offline_servers();
    stats.avg_score = cluster_stats.avg_score();
    stats.max_score = cluster_stats.max_score();
    stats.min_score = cluster_stats.min_score();
    stats.best_server = cluster_stats.best_server();
    stats.worst_server = cluster_stats.worst_server();

    return true;
}

bool GrpcClient::QueryPerformance(
    const std::string& server_name,
    const QDateTime& start_time,
    const QDateTime& end_time,
    std::vector<PerformanceRecord>& records) {

    monitor::proto::QueryPerformanceRequest request;
    monitor::proto::QueryPerformanceResponse response;
    grpc::ClientContext context;

    // 设置请求参数
    request.set_server_name(server_name);

    // 设置时间范围
    *request.mutable_time_range()->mutable_start_time() = TimeUtils::QDateTimeToTimestamp(start_time);
    *request.mutable_time_range()->mutable_end_time() = TimeUtils::QDateTimeToTimestamp(end_time);

    // 设置分页
    auto* pagination = request.mutable_pagination();
    pagination->set_page(1);
    pagination->set_page_size(1000);

    // 调用RPC
    grpc::Status status = stub_->QueryPerformance(&context, request, &response);
    if (!status.ok()) {
        qDebug() << "QueryPerformance RPC failed: " << status.error_message().c_str();
        return false;
    }

    // 转换性能数据
    for (const auto& record : response.records()) {
        PerformanceRecord perf_record;
        perf_record.server_name = record.server_name();
        perf_record.timestamp = TimeUtils::TimestampToQDateTime(record.timestamp());
        perf_record.cpu_percent = record.cpu_percent();
        perf_record.usr_percent = record.usr_percent();
        perf_record.system_percent = record.system_percent();
        perf_record.nice_percent = record.nice_percent();
        perf_record.idle_percent = record.idle_percent();
        perf_record.io_wait_percent = record.io_wait_percent();
        perf_record.irq_percent = record.irq_percent();
        perf_record.soft_irq_percent = record.soft_irq_percent();
        perf_record.load_avg_1 = record.load_avg_1();
        perf_record.load_avg_3 = record.load_avg_3();
        perf_record.load_avg_15 = record.load_avg_15();
        perf_record.mem_used_percent = record.mem_used_percent();
        perf_record.mem_total = record.mem_total();
        perf_record.mem_free = record.mem_free();
        perf_record.mem_avail = record.mem_avail();
        perf_record.disk_util_percent = record.disk_util_percent();
        perf_record.send_rate = record.send_rate();
        perf_record.rcv_rate = record.rcv_rate();
        records.push_back(perf_record);
    }

    return true;
}

