    const std::string& server_name,
    const QDateTime& start_time,
    const QDateTime& end_time,
    std::vector<AnomalyRecord>& anomalies) {

    monitor::proto::QueryAnomalyRequest request;
    monitor::proto::QueryAnomalyResponse response;
    grpc::ClientContext context;

    // 设置请求参数
    request.set_server_name(server_name);

    // 设置时间范围
    *request.mutable_time_range()->mutable_start_time() = TimeUtils::QDateTimeToTimestamp(start_time);
    *request.mutable_time_range()->mutable_end_time() = TimeUtils::QDateTimeToTimestamp(end_time);

    // 设置默认阈值
    request.set_cpu_threshold(80.0f);
    request.set_mem_threshold(90.0f);
    request.set_disk_threshold(85.0f);
    request.set_change_rate_threshold(0.5f);

    // 设置分页
    auto* pagination = request.mutable_pagination();
    pagination->set_page(1);
    pagination->set_page_size(100);

    // 调用RPC
    grpc::Status status = stub_->QueryAnomaly(&context, request, &response);
    if (!status.ok()) {
        qDebug() << "QueryAnomaly RPC failed: " << status.error_message().c_str();
        return false;
    }

    // 转换异常数据
    for (const auto& anomaly : response.anomalies()) {
        AnomalyRecord anomaly_record;
        anomaly_record.server_name = anomaly.server_name();
        anomaly_record.timestamp = TimeUtils::TimestampToQDateTime(anomaly.timestamp());
        anomaly_record.anomaly_type = anomaly.anomaly_type();
        anomaly_record.severity = anomaly.severity();
        anomaly_record.value = anomaly.value();
        anomaly_record.threshold = anomaly.threshold();
        anomaly_record.metric_name = anomaly.metric_name();
        anomalies.push_back(anomaly_record);
    }

    return true;
}

