    // 加载现有告警配置
    ui->statusBar->showMessage(QString("正在加载 %1 的告警配置...").arg(server_name_));

    // 这里应该从数据库或配置文件加载告警配置
    // 为了演示，我们使用默认配置

    // 设置服务器名称
    ui->serverNameLabel->setText(server_name_);

