    ui->webhookLineEdit->setText("https://example.com/webhook");

    ui->statusBar->showMessage(QString("已加载 %1 的告警配置").arg(server_name_));
}

void AlarmConfigDialog::SaveAlarmConfig() {
    // 保存告警配置
    ui->statusBar->showMessage(QString("正在保存 %1 的告警配置...").arg(server_name_));

    // 验证输入
    if (ui->warningThresholdSpinBox->value() >= ui->criticalThresholdSpinBox->value()) {
        QMessageBox::warning(this, "警告", "警告阈值必须小于严重阈值");
        return;
    }

    if (ui->emailCheckBox->isChecked() && ui->emailLineEdit->text().isEmpty()) {
        QMessageBox::warning(this, "警告", "请输入邮箱地址");
        return;
    }

    if (ui->webhookCheckBox->isChecked() && ui->webhookLineEdit->text().isEmpty()) {
        QMessageBox::warning(this, "警告", "请输入Webhook地址");
        return;
    }

    // 这里应该将配置保存到数据库或配置文件
    // 为了演示，我们只显示保存成功的消息

    QMessageBox::information(this, "成功", QString("已保存 %1 的告警配置").arg(server_name_));
    ui->statusBar->showMessage(QString("已保存 %1 的告警配置").arg(server_name_));
    accept();
}

void AlarmConfigDialog::ResetAlarmConfig() {
    // 重置告警配置
    if (QMessageBox::question(this, "确认", "确定要重置告警配置吗？") == QMessageBox::Yes) {
        InitializeUI();
        ui->statusBar->showMessage(QString("已重置 %1 的告警配置").arg(server_name_));
    }
}

