void AlarmConfigDialog::on_metricCombo_currentTextChanged(const QString &arg1) {
    // 根据选择的指标类型更新UI控件
    qDebug() << "切换指标类型: " << arg1;

    // 根据指标类型设置不同的阈值范围
    if (arg1 == "CPU" || arg1 == "内存" || arg1 == "磁盘") {
        ui->warningThresholdSpinBox->setRange(0.0, 100.0);
        ui->criticalThresholdSpinBox->setRange(0.0, 100.0);
        ui->thresholdUnitLabel->setText("%");
    } else if (arg1 == "网络") {
        ui->warningThresholdSpinBox->setRange(0.0, 10000.0);
        ui->criticalThresholdSpinBox->setRange(0.0, 10000.0);
        ui->thresholdUnitLabel->setText("KB/s");
    } else if (arg1 == "负载") {
        ui->warningThresholdSpinBox->setRange(0.0, 10.0);
        ui->criticalThresholdSpinBox->setRange(0.0, 10.0);
        ui->thresholdUnitLabel->setText("负载值");
    }

    // 设置默认阈值
    ui->warningThresholdSpinBox->setValue(80.0);
    ui->criticalThresholdSpinBox->setValue(90.0);
}
