--- monitor_structs.h ---
#pragma once

#include <stdint.h>

/*
 * 内核模块与用户空间共享的数据结构定义
 * 这些结构体必须与内核模块中的定义保持一致
 */

#ifdef __cplusplus
extern "C" {
#endif

/* 软中断统计结构体 */
struct softirq_stat {
    char cpu_name[16];      /* CPU 名称，如 "cpu0" */
    uint64_t hi;            /* HI_SOFTIRQ - 高优先级软中断 */
    uint64_t timer;         /* TIMER_SOFTIRQ - 定时器软中断 */
    uint64_t net_tx;        /* NET_TX_SOFTIRQ - 网络发送软中断 */
    uint64_t net_rx;        /* NET_RX_SOFTIRQ - 网络接收软中断 */
    uint64_t block;         /* BLOCK_SOFTIRQ - 块设备软中断 */
    uint64_t irq_poll;      /* IRQ_POLL_SOFTIRQ - 中断轮询软中断 */
    uint64_t tasklet;       /* TASKLET_SOFTIRQ - tasklet 软中断 */
    uint64_t sched;         /* SCHED_SOFTIRQ - 调度软中断 */
    uint64_t hrtimer;       /* HRTIMER_SOFTIRQ - 高精度定时器软中断 */
    uint64_t rcu;           /* RCU_SOFTIRQ - RCU 软中断 */
};

/* CPU 负载统计结构体 */
struct cpu_load {
    float load_avg_1;       /* 1 分钟平均负载 */
    float load_avg_3;       /* 5 分钟平均负载 (注：实际是 5 分钟) */
    float load_avg_15;      /* 15 分钟平均负载 */
};

/* CPU 使用率统计结构体 */
struct cpu_stat {
    char cpu_name[16];      /* CPU 名称 */
    uint64_t user;          /* 用户态时间 */
    uint64_t nice;          /* 低优先级用户态时间 */
    uint64_t system;        /* 内核态时间 */
    uint64_t idle;          /* 空闲时间 */
    uint64_t iowait;        /* I/O 等待时间 */
    uint64_t irq;           /* 硬中断时间 */
    uint64_t softirq;       /* 软中断时间 */
    uint64_t steal;         /* 虚拟化偷取时间 */
    uint64_t guest;         /* 虚拟机运行时间 */
    uint64_t guest_nice;    /* 低优先级虚拟机运行时间 */
};

#ifdef __cplusplus
}
#endif

--- MetricCollector ---
#include "monitor/metric_collector.h"

#include <unistd.h>

#include <memory>

#include "monitor/cpu_load_monitor.h"
#include "monitor/cpu_softirq_monitor.h"
#include "monitor/cpu_stat_monitor.h"
#include "monitor/disk_monitor.h"
#include "monitor/mem_monitor.h"
#include "monitor/host_info_monitor.h"

#ifdef ENABLE_EBPF
#include "monitor/net_ebpf_monitor.h"
#else
#include "monitor/net_monitor.h"
#endif

namespace monitor {

MetricCollector::MetricCollector() {
  // 获取主机名
  char hostname[256];
  if (gethostname(hostname, sizeof(hostname)) == 0) {
    hostname_ = hostname;
  } else {
    hostname_ = "unknown";
  }

  // 初始化所有监控器
  monitors_.push_back(std::make_unique<CpuLoadMonitor>());
  monitors_.push_back(std::make_unique<CpuStatMonitor>());
  monitors_.push_back(std::make_unique<CpuSoftIrqMonitor>());
  monitors_.push_back(std::make_unique<MemMonitor>());
#ifdef ENABLE_EBPF
  monitors_.push_back(std::make_unique<NetEbpfMonitor>());
#else
  monitors_.push_back(std::make_unique<NetMonitor>());
#endif
  monitors_.push_back(std::make_unique<DiskMonitor>());
  monitors_.push_back(std::make_unique<HostInfoMonitor>());
}

MetricCollector::~MetricCollector() {
  for (auto& monitor : monitors_) {
    monitor->Stop();
  }
}

void MetricCollector::CollectAll(monitor::proto::MonitorInfo* monitor_info) {
  if (!monitor_info) {
    return;
  }

  // 设置主机名
  monitor_info->set_name(hostname_);

  // 调用每个监控器的 UpdateOnce 方法
  for (auto& monitor : monitors_) {
    monitor->UpdateOnce(monitor_info);
  }
}

}  // namespace monitor
