    SleItem responsiveness;
    SleItem reliability;
    SleItem rf_health;

    // --- service_health（9 项）---
    SleItem dns_service;
    SleItem tcp_connect;
    SleItem tcp_rtt;
    SleItem http_access;
    SleItem captive_portal;
    SleItem active_dns;
    SleItem active_tcp;
    SleItem active_https;
    SleItem active_portal;

    /// 警告列表
