    EXPECT_DOUBLE_EQ(lo, 40.0);
    EXPECT_DOUBLE_EQ(hi, 95.0);
}

TEST(HistoryTest, EmptyArray) {
    const HistorySeries series = weaknet::dashboard::parse_history("[]");
    EXPECT_TRUE(series.empty());
