    ASSERT_EQ(snap.actions.size(), 1u);
    EXPECT_EQ(snap.actions[0].priority, 1);
    EXPECT_EQ(snap.actions[0].action_id, "restart_dns_resolver");
    EXPECT_EQ(snap.summary_template, "DNS 解析偏慢");
