import gzip, re, sys

# 解析 Packages.gz -> {name: (filename, depends)}
pools = {}
with gzip.open('/tmp/pkgs.gz', 'rt', encoding='utf-8', errors='replace') as f:
    cur = {}
    for line in f:
        line = line.rstrip('\n')
        if not line:
            if 'Package' in cur and 'Filename' in cur:
                pools[cur['Package']] = (cur['Filename'], cur.get('Depends', ''))
            cur = {}
            continue
        if line.startswith('Package:'):
            cur['Package'] = line.split(':',1)[1].strip()
        elif line.startswith('Filename:'):
            cur['Filename'] = line.split(':',1)[1].strip()
        elif line.startswith('Depends:'):
            cur['Depends'] = line.split(':',1)[1].strip()

print("索引包数:", len(pools))

roots = ['qtbase5-dev', 'qtbase5-dev-tools', 'libqt5gui5', 'libqt5widgets5',
         'libqt5core5a', 'libqt5dbus5', 'libqt5network5']

# 递归解析 Depends，忽略版本约束与 alternatives（取第一个）
seen = set()
order = []
def resolve(name):
    if name in seen: return
    seen.add(name)
    if name not in pools:
        return
    fname, deps = pools[name]
    order.append((name, fname))
    if not deps: return
    # 去掉版本约束 (>= x) 等
    for part in deps.split(','):
        alt = part.split('|')[0].strip()
        dep = re.sub(r'\s*\(.*?\)', '', alt).strip()
        dep = dep.split(':')[0]   # 去掉 multiarch 后缀
        if dep:
            resolve(dep)

for r in roots:
    resolve(r)

print("递归展开包数:", len(order))
for n, fn in order:
    print(f"  {n:35s} {fn}")
PYEOF

