#include <stdio.h>
#include <string.h>
#include "weaknet_client.h"

int main(void) {
    static char buf[64 * 1024];
    static char err[512];
    const char* names[] = {"network_experience", "diagnosis", "history", "interfaces"};
    if (!weaknet_init()) { printf("init FAILED\n"); return 1; }
    printf("init OK\n");
    for (int i = 0; i < 4; i++) {
        memset(buf, 0, sizeof(buf)); memset(err, 0, sizeof(err));
        int ok = 0;
        if (i == 0) ok = weaknet_get_network_experience(buf, sizeof(buf), err, sizeof(err));
        else if (i == 1) ok = weaknet_get_diagnosis(buf, sizeof(buf), err, sizeof(err));
        else if (i == 2) ok = weaknet_get_history(NULL, "", "", 5, buf, sizeof(buf), err, sizeof(err));
        else ok = weaknet_get_interfaces(buf, sizeof(buf), err, sizeof(err));
        printf("%-20s ok=%d len=%zu err=%s\n", names[i], ok, strlen(buf), err);
        if (ok && strlen(buf) > 0) printf("   head: %.120s\n", buf);
        else if (err[0]) printf("   ERR: %s\n", err);
    }
    weaknet_cleanup();
    return 0;
}
